#include "Classifier.h"
#include "ap_int.h"
#include "Exp.h"
#include "bias.h"

// Split headers generated by the script below
#include "svs_0.h"
#include "svs_1.h"
#include "alphas_0.h"
#include "alphas_1.h"
#include "sv_norms_0.h"
#include "sv_norms_1.h"

static const int LANES     = 16;
static const int PIX_U     = 16;
static const int PIX_GROUP = IMG_SIZE / PIX_U;     // 49
static const int RECON_U   = 4;                    // unroll reconstruct
static const int NSV0      = 96;                   // padded
static const int NSV1      = 96;                   // padded

ap_fixed<24,14> load_and_calc_norm(hls::stream<axis_t> &in_stream,
                                  ap_fixed<8,7> x_local[IMG_SIZE]) {
#pragma HLS INLINE off
    ap_fixed<24,14> calculated_norm = 0;

    for (int i = 0; i < IMG_SIZE/8; i++) {
#pragma HLS LOOP_TRIPCOUNT min=98 max=98 avg=98
#pragma HLS PIPELINE II=1
        axis_t packet = in_stream.read();
        ap_uint<64> data = packet.data;

        for (int p = 0; p < 8; p++) {
#pragma HLS UNROLL
            ap_fixed<8,7> val;
            val(7,0) = data.range((p<<3)+7, (p<<3));
            x_local[(i<<3)+p] = val;

            ap_fixed<16,14> sq = val * val;
            calculated_norm += sq;
        }
    }
    return calculated_norm;
}

void compute_and_output(ap_fixed<8,7> x_local[IMG_SIZE],
                        ap_fixed<24,14> x_norm_in,
                        hls::stream<result_pkt> &out_stream,
                        int n, int num_images) {
#pragma HLS INLINE off

    // Two machines
    ap_fixed<32,16> partial_sum[2][LANES];
#pragma HLS ARRAY_PARTITION variable=partial_sum complete dim=1
#pragma HLS ARRAY_PARTITION variable=partial_sum complete dim=2

    // init
    for (int m=0; m<2; m++) {
#pragma HLS UNROLL
        for (int k=0; k<LANES; k++) {
#pragma HLS UNROLL
            partial_sum[m][k] = 0;
        }
    }

    // Iterate batches for each machine (both have same padded length)
    for (int i = 0; i < NSV0; i += LANES) {
#pragma HLS LOOP_TRIPCOUNT min=6 max=6 avg=6

        ap_fixed<32,16> dot[2][LANES];
#pragma HLS ARRAY_PARTITION variable=dot complete dim=1
#pragma HLS ARRAY_PARTITION variable=dot complete dim=2

        for (int m=0; m<2; m++) {
#pragma HLS UNROLL
            for (int k=0; k<LANES; k++) {
#pragma HLS UNROLL
                dot[m][k] = 0;
            }
        }

        // Dot products over 16-pixel groups
        for (int jg = 0; jg < PIX_GROUP; jg++) {
#pragma HLS LOOP_TRIPCOUNT min=49 max=49 avg=49
#pragma HLS PIPELINE II=1

            ap_fixed<8,7> xpix[PIX_U];
#pragma HLS ARRAY_PARTITION variable=xpix complete dim=1
            for (int p=0; p<PIX_U; p++) {
#pragma HLS UNROLL
                xpix[p] = x_local[jg*PIX_U + p];
            }

            // machine loop (unrolled => two parallel datapaths)
            for (int m=0; m<2; m++) {
#pragma HLS UNROLL
                for (int k=0; k<LANES; k++) {
#pragma HLS UNROLL
                    ap_fixed<32,16> sum_pix = 0;

                    for (int p=0; p<PIX_U; p++) {
#pragma HLS UNROLL
                        ap_fixed<8,7> xi =
                            (m==0) ? svs_0[i+k][jg*PIX_U + p]
                                   : svs_1[i+k][jg*PIX_U + p];
                        sum_pix += ap_fixed<16,14>(xi * xpix[p]);
                    }
                    dot[m][k] += sum_pix;
                }
            }
        }

        // Reconstruct + exp + alpha*K
        // Do 4 lanes per cycle (RECON_U)
        for (int kk = 0; kk < LANES; kk += RECON_U) {
#pragma HLS LOOP_TRIPCOUNT min=4 max=4 avg=4
#pragma HLS PIPELINE II=1

            for (int m=0; m<2; m++) {
#pragma HLS UNROLL
                for (int r=0; r<RECON_U; r++) {
#pragma HLS UNROLL
                    int k = kk + r;

                    ap_fixed<32,16> svn =
                        (m==0) ? sv_norms_0[i+k] : sv_norms_1[i+k];
                    ap_fixed<32,16> alpha =
                        (m==0) ? ap_fixed<32,16>(alphas_0[i+k])
                               : ap_fixed<32,16>(alphas_1[i+k]);

                    ap_fixed<32,16> dist_sq =
                        ap_fixed<32,16>(x_norm_in) + svn - (dot[m][k] << 1);

                    if (dist_sq < 0) dist_sq = 0;

                    ap_fixed<22,1> K = (ap_fixed<22,1>)compute_exp(-(dist_sq >> 10));
                    partial_sum[m][k] += alpha * ap_fixed<32,16>(K);
                }
            }
        }
    }

    ap_fixed<32,16> sum = 0;
    for (int m=0; m<2; m++) {
#pragma HLS UNROLL
        for (int k=0; k<LANES; k++) {
#pragma HLS UNROLL
            sum += partial_sum[m][k];
        }
    }

    result_pkt out_val;
    out_val.data = (ap_fixed<32,16>)(sum + bias[0]);
    out_val.keep = -1;
    out_val.strb = -1;
    out_val.last = (n == num_images - 1) ? 1 : 0;
    out_stream.write(out_val);
}

void classify(hls::stream<axis_t> &in_stream,
              hls::stream<result_pkt> &out_stream,
              int num_images) {
#pragma HLS INTERFACE axis port=in_stream
#pragma HLS INTERFACE axis port=out_stream
#pragma HLS INTERFACE s_axilite port=num_images bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Each split SV array needs the same banking as your original
#pragma HLS ARRAY_RESHAPE  variable=svs_0 cyclic factor=LANES dim=2
#pragma HLS ARRAY_PARTITION variable=svs_0 cyclic factor=LANES dim=1
#pragma HLS ARRAY_RESHAPE  variable=svs_1 cyclic factor=LANES dim=2
#pragma HLS ARRAY_PARTITION variable=svs_1 cyclic factor=LANES dim=1

#pragma HLS ARRAY_PARTITION variable=alphas_0 cyclic factor=LANES dim=1
#pragma HLS ARRAY_PARTITION variable=alphas_1 cyclic factor=LANES dim=1
#pragma HLS ARRAY_PARTITION variable=sv_norms_0 cyclic factor=LANES dim=1
#pragma HLS ARRAY_PARTITION variable=sv_norms_1 cyclic factor=LANES dim=1

    Batch_Loop: for (int n = 0; n < num_images; n++) {
#pragma HLS LOOP_TRIPCOUNT min=2601 max=2601 avg=2601
#pragma HLS DATAFLOW
        ap_fixed<8,7> x_local[IMG_SIZE];
#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=LANES dim=1

        ap_fixed<24,14> internal_norm = load_and_calc_norm(in_stream, x_local);
        compute_and_output(x_local, internal_norm, out_stream, n, num_images);
    }
}
